                                                    const checkoutSize = document.getElementById(
                                                        'checkout-size');

                                                    const colorSelect = document.querySelector(
                                                        'select[name="color"]');
                                                    const sizeSelect = document.querySelector(
                                                        'select[name="size"]');

                                                    // Đồng bộ số lượng
                                                    quantityInput.addEventListener('input', function() {
                                                        checkoutQty.value = this.value;
                                                    });

                                                    // Đồng bộ biến thể màu
                                                    if (colorSelect) {
                                                        colorSelect.addEventListener('change', function() {
                                                            checkoutColor.value = this.value;
                                                        });
                                                        checkoutColor.value = colorSelect.value;
                                                    }

                                                    // Đồng bộ biến thể size
                                                    if (sizeSelect) {
                                                        sizeSelect.addEventListener('change', function() {
                                                            checkoutSize.value = this.value;
                                                        });
                                                        checkoutSize.value = sizeSelect.value;
                                                    }
                                                });
